        try:
            return int(v)
        except:
            return 0

    def p(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return i(v[0]), i(v[1])
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("col", "row"), ("pos_x", "pos_y")):
                if a in v and b in v:
                    return i(v[a]), i(v[b])
        return None

    W = i(o.get("grid_width", o.get("width", 0)))
    H = i(o.get("grid_height", o.get("height", 0)))

    me = p(o.get("self_position")) or p(o.get("position")) or p(o.get("agent_position")) or (0, 0)
    opp = (
        p(o.get("opponent_position"))
        or p(o.get("enemy_position"))
        or p(o.get("opponent"))
        or p(o.get("enemy"))
        or (W // 2, H // 2)
    )

    blocked = set()
    for k in ("obstacles", "walls", "blocked", "blocked_cells"):
        for x in o.get(k) or []:
            q = p(x)
            if q is not None:
                blocked.add(q)

    resources = []
    for k in ("resources", "food", "items", "targets", "collectibles", "goals"):
        for x in o.get(k) or []:
            q = p(x)
            if q is not None:
                resources.append(q)

    owned = set()
    for k in ("territory", "owned", "control", "claimed", "my_cells"):
        for x in o.get(k) or []:
            q = p(x)
            if q is not None:
                owned.add(q)

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    bestv = None

    def inside(x, y):
        return x >= 0 and y >= 0 and (not W or x < W) and (not H or y < H)

    for dx, dy in moves:
        x, y = me[0] + dx, me[1] + dy
        if not inside(x, y) or (x, y) in blocked:
            continue

        dist_opp = abs(x - opp[0]) + abs(y - opp[1])
        center = abs(x - W // 2) + abs(y - H // 2) if W and H else 0

        if resources:
            dist_res = min(abs(x - rx) + abs(y - ry) for rx, ry in resources)
            # Prefer closer resources, but don't blindly rush the opponent.
            v = (dist_res, dist_opp, center, dx == 0 and dy == 0, abs(dx) + abs(dy))
        else:
            # Territory / pursuit fallback: stay active, prefer moving toward enemy
            # while avoiding blocked edges and keeping some centrality.
            dist_my = abs(x - me[0]) + abs(y - me[1])
            frontier = 0 if (x, y) in owned else 1
            v = (dist_opp, frontier, center, dx == 0 and dy == 0, dist_my)

        if bestv is None or v < bestv:
            bestv = v
            best = (dx, dy)

    if bestv is not None:
        return [best[0], best[1]]

